begin;
select no_plan();
select has_column('public','deadline_reminders','delivery_mode','each reminder persists its delivery mode');
select col_default_is('public','deadline_reminders','delivery_mode', 'local'::text, 'legacy insertion defaults to local delivery');
insert into auth.users(id,email,email_confirmed_at,is_anonymous) values
('55555555-5555-4555-8555-555555555555','mode-owner@example.invalid',now(),false),
('66666666-6666-4666-8666-666666666666','mode-other@example.invalid',now(),false);
insert into public.deadline_calculations(id,owner_id,input,result_snapshot) values
('bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbb1','55555555-5555-4555-8555-555555555555','{}','{"status":"provisional","dueDate":"2030-01-07","metadata":{"calendarVersion":"original"}}'),
('bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbb2','55555555-5555-4555-8555-555555555555','{}','{"status":"provisional","dueDate":"2030-01-07","metadata":{"calendarVersion":"original"}}');
set local role authenticated;
set local request.jwt.claims = '{"sub":"55555555-5555-4555-8555-555555555555","role":"authenticated","is_anonymous":false}';
select lives_ok($$select public.schedule_deadline_reminder('bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbb1',1,9)$$,'old scheduler remains supported');
select lives_ok($$select public.schedule_deadline_reminder_for_mode('bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbb2',1,9,'brevo')$$,'owner explicitly schedules external reminder');
select is((select delivery_mode from public.deadline_reminders where calculation_id='bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbb1'),'local','old schedule never promotes local delivery');
select is((select delivery_mode from public.deadline_reminders where calculation_id='bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbb2'),'brevo','explicit external schedule persists Brevo');
reset role;
update public.deadline_reminders set send_at=now()-interval '1 minute' where owner_id='55555555-5555-4555-8555-555555555555';
create temp table external_claims(id uuid,token uuid);
grant all on external_claims to service_role;
set local role service_role;
create temp table local_claims as select * from public.claim_deadline_reminders(20);
select is((select count(*) from local_claims),1::bigint,'legacy worker claims local only');
select lives_ok($$insert into external_claims select * from public.claim_deadline_reminders_for_mode('brevo',20)$$,'external worker has a mode-scoped claim');
select is((select count(*) from external_claims),1::bigint,'external worker obtains its own pending generation');
select throws_ok($$select * from public.claim_deadline_reminders_for_mode('other',20)$$,'22023',null,'unknown delivery mode fails closed');
reset role;
update public.deadline_reminders set claimed_at=now()-interval '6 minutes' where owner_id='55555555-5555-4555-8555-555555555555';
set local role service_role;
select is_empty($$select * from public.claim_deadline_reminders_for_mode('brevo',20)$$,'expired external claim is not resent');
reset role;
select is((select status from public.deadline_reminders where calculation_id='bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbb1'),'processing','external lease maintenance never mutates local row');
select is((select status from public.deadline_reminders where calculation_id='bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbb2'),'uncertain','external expired lease is uncertain');
set local role authenticated;
set local request.jwt.claims = '{"sub":"55555555-5555-4555-8555-555555555555","role":"authenticated","is_anonymous":false}';
select throws_ok($$select * from public.claim_deadline_reminders_for_mode('brevo',20)$$,'42501',null,'user cannot claim external queue');
select throws_ok($$select public.schedule_deadline_reminder_for_mode('bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbb1',1,9,'other')$$,'22023',null,'unknown schedule mode is rejected');
select throws_ok($$update public.deadline_reminders set delivery_mode='brevo'$$,'42501',null,'user cannot promote a local row');
set local request.jwt.claims = '{"sub":"66666666-6666-4666-8666-666666666666","role":"authenticated","is_anonymous":false}';
select throws_ok($$select public.schedule_deadline_reminder_for_mode('bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbb1',1,9,'brevo')$$,'P0002',null,'external schedule cannot target another owner');
set local request.jwt.claims = '{"sub":"55555555-5555-4555-8555-555555555555","role":"authenticated","is_anonymous":false}';
select lives_ok($$select public.list_deadline_reminders_for_mode(array['bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbb1','bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbb2']::uuid[],'brevo')$$,'owner can list only external mode safely');
select is(jsonb_array_length(public.list_deadline_reminders_for_mode(array['bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbb1','bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbb2']::uuid[],'brevo')),1,'listing excludes local rows');
select is(public.list_deadline_reminders_for_mode(array['bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbb2']::uuid[],'brevo')->0->>'delivery_mode','brevo','listing labels external delivery');
select ok(not (public.list_deadline_reminders_for_mode(array['bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbb2']::uuid[],'brevo')->0 ?| array['claim_token','email','snapshot_metadata']),'listing contains no privileged payload');
select throws_ok($$select public.list_deadline_reminders_for_mode(array[]::uuid[],'brevo')$$,'22023',null,'empty listing is invalid');
set local request.jwt.claims = '{"sub":"66666666-6666-4666-8666-666666666666","role":"authenticated","is_anonymous":false}';
select is(public.list_deadline_reminders_for_mode(array['bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbb2']::uuid[],'brevo'),'[]'::jsonb,'external listing isolates owners');
set local role anon;
select throws_ok($$select public.schedule_deadline_reminder_for_mode('bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbb1',1,9,'brevo')$$,'42501',null,'anon cannot schedule external messages');
select throws_ok($$select * from public.claim_deadline_reminders_for_mode('brevo',20)$$,'42501',null,'anon cannot claim external queue');
reset role;
update public.deadline_reminders set status='pending',send_at=now()-interval '2 hours' where delivery_mode='local' and owner_id='55555555-5555-4555-8555-555555555555';
set local role service_role;
select is_empty($$select * from public.claim_deadline_reminders_for_mode('brevo',20)$$,'external maintenance does not claim expired local row');
reset role;
select is((select status from public.deadline_reminders where calculation_id='bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbb1'),'pending','external window maintenance leaves local state untouched');
set local role authenticated;
set local request.jwt.claims = '{"sub":"55555555-5555-4555-8555-555555555555","role":"authenticated","is_anonymous":false}';
select is(public.cancel_deadline_reminders(null),2,'owner can cancel both modes in one action');
reset role;
select * from finish();
rollback;
